#define M7 510510
static int32_t acc7[M7 + 1];
static int acc7_init = 0;

static void init_acc7(void) {
    if (acc7_init) return;
    uint8_t *phi7 = (uint8_t *)malloc(M7);
    memset(phi7, 1, M7);
    const int ps[7] = {2, 3, 5, 7, 11, 13, 17};
    for (int k = 0; k < 7; k++) {
        int p = ps[k];
        for (int i = 0; i < M7; i += p) {
            phi7[i] = 0;
        }
    }
    int32_t s = 0;
    acc7[0] = 0;
    for (int i = 0; i < M7; i++) {
        s += phi7[i];
        acc7[i + 1] = s;
    }
    free(phi7);
    acc7_init = 1;
}

static int64_t isqrt64(int64_t n) {
    if (n <= 0) return 0;
    int64_t x = (int64_t)sqrt((double)n);
    while ((x + 1) * (x + 1) <= n) x++;
    while (x * x > n) x--;
    return x;
}

static int64_t sieve_small(int64_t n) {
    if (n <= 2) return 0;
    if (n == 3) return 1;
    int64_t size = n / 2;
    uint8_t *sieve = (uint8_t *)malloc(size);
    memset(sieve, 1, size);
    sieve[0] = 0;
    int64_t limit = isqrt64(n - 1) / 2;
    for (int64_t i = 1; i <= limit; i++) {
        if (sieve[i]) {
            int64_t p = 2 * i + 1;
            for (int64_t j = (p * p) / 2; j < size; j += p) {
                sieve[j] = 0;
            }
        }
    }
    int64_t count = 1;
    for (int64_t i = 1; i < size; i++) {
        count += sieve[i];
    }
    free(sieve);
    return count;
}

#define MEMO_V_MAX 20000
#define MEMO_C_MAX 120
static int32_t memo_tbl[MEMO_C_MAX][MEMO_V_MAX];
static uint8_t memo_set[MEMO_C_MAX][MEMO_V_MAX];

static int64_t phi(int64_t v, int64_t c, const int32_t *primes) {
    if (c == 0) return v;
    if (c == 1) return (v + 1) >> 1;
    if (c == 2) return v - (v >> 1) - v / 3 + v / 6;
    if (c == 7) {
        int64_t q = v / M7;
        int64_t r = v % M7;
        return q * 92160 + acc7[r + 1];
    }
    if (v < primes[c - 1]) {
        return v > 0 ? 1 : 0;
    }
    if (c < MEMO_C_MAX && v < MEMO_V_MAX) {
        if (memo_set[c][v]) return memo_tbl[c][v];
        int64_t res = phi(v, c - 1, primes) - phi(v / primes[c - 1], c - 1, primes);
        memo_set[c][v] = 1;
        memo_tbl[c][v] = (int32_t)res;
        return res;
    }
    return phi(v, c - 1, primes) - phi(v / primes[c - 1], c - 1, primes);
}

int64_t count_primes_below(int64_t n) {
    if (n <= 100000) {
        return sieve_small(n);
    }
    init_acc7();
    memset(memo_set, 0, sizeof(memo_set));

    int64_t x = n - 1;
    int64_t y = (int64_t)pow((double)x, 0.37);
    int64_t z = x / y;

    int64_t size = (z + 1) / 2;
    uint8_t *sieve = (uint8_t *)malloc(size);
    memset(sieve, 1, size);
    sieve[0] = 0;
    int64_t r = isqrt64(z) / 2;
    for (int64_t i = 1; i <= r; i++) {
        if (sieve[i]) {
            int64_t p = 2 * i + 1;
            for (int64_t j = (p * p) / 2; j < size; j += p) {
                sieve[j] = 0;
            }
        }
    }

    int32_t *pi_tbl = (int32_t *)malloc((z + 1) * sizeof(int32_t));
    int32_t *primes = (int32_t *)malloc((size + 1) * sizeof(int32_t));
    int32_t pcount = 0;
    pi_tbl[0] = 0;
    pi_tbl[1] = 0;
    if (z >= 2) {
        primes[pcount++] = 2;
        pi_tbl[2] = 1;
    }
    for (int64_t v = 3; v <= z; v++) {
        if ((v & 1) && sieve[v >> 1]) {
            primes[pcount++] = (int32_t)v;
        }
        pi_tbl[v] = pcount;
    }
    free(sieve);

    int64_t a = pi_tbl[y];
    int64_t b = pi_tbl[isqrt64(x)];

    int64_t p2 = 0;
    for (int64_t i = a; i < b; i++) {
        p2 += pi_tbl[x / primes[i]] - i;
    }

    int64_t ans = phi(x, a, primes) + a - 1 - p2;

    free(pi_tbl);
    free(primes);
    return ans;
}

